def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    window = history[-20:] if n > 20 else history
    score = 0
    for i in range(1, len(window)):
        my_prev = window[i-1][0]
        opp_curr = window[i][1]
        if my_prev == 'D':
            if opp_curr == 'C':
                score += 2
            else:
                score -= 3
        else:
            if opp_curr == 'D':
                score -= 2

    last_my, last_opp = history[-1]

    if last_opp == 'D':
        if last_my == 'D':
            run = 0
            for m, o in reversed(history):
                if m == 'D' and o == 'D':
                    run += 1
                else:
                    break
            if run >= 2 and rng.random() < 0.4:
                return 'C'
            return 'D'
        else:
            if n >= 2 and history[-2][0] == 'D':
                return 'C'
            return 'D'
    else:
        if last_my == 'D':
            if score > 0:
                return 'D'
            else:
                if n >= 2 and history[-2][0] == 'C':
                    if rng.random() < 0.3:
                        return 'D'
                    return 'C'
                return 'C'
        else:
            if score > 5:
                if rng.random() < 0.7:
                    return 'D'
                return 'C'
            if n >= 5:
                last5 = history[-5:]
                if all(m == 'C' and o == 'C' for m, o in last5):
                    if rng.random() < 0.1:
                        return 'D'
            return 'C'
